package io.github.juliarezende521.workjourney.contract;import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;import static org.junit.jupiter.api.Assertions.*;
class ContractRequestReaderTest{private final ContractRequestReader reader=new ContractRequestReader(new ObjectMapper());@Test void readsExactContract()throws Exception{var value=reader.read(json("{\"effectiveFrom\":\"2026-11-01\",\"countryCode\":\"BR\",\"employmentType\":\"FULL_TIME\",\"weeklyMinutes\":2400}"));assertEquals(2400,value.weeklyMinutes());}@Test void rejectsUnknownAndInvalidType(){assertThrows(InvalidContract.class,()->reader.read(json("{\"admin\":true}")));assertThrows(InvalidContract.class,()->reader.read(json("{\"effectiveFrom\":\"2026-11-01\",\"countryCode\":\"BR\",\"employmentType\":\"OTHER\",\"weeklyMinutes\":2400}")));}private MockHttpServletRequest json(String body){var request=new MockHttpServletRequest();request.setContent(body.getBytes(StandardCharsets.UTF_8));return request;}}
